using Lyra.Common;
using Lyra.Imaging.Content;
using Lyra.Imaging.Decoding.Decoders;
using Lyra.Imaging.Decoding.Decoders.Raw;
using Lyra.Imaging.Interop;
using Lyra.Imaging.Tests.Support;
using SkiaSharp;
using Xunit;

namespace Lyra.Imaging.Tests.Decoding;

/// <summary>
/// Camera raw through the real LibRaw wrapper, on DNGs generated by <see cref="DngBuilder"/>.
/// Self-skips when the wrapper is not built for this platform.
/// </summary>
public class RawDecoderTests
{
    private static readonly Lazy<bool> NativeRawReady = new(() => NativeWrapper.TryLoad("libraw_native", typeof(RawDecoder).Assembly));

    private static void RequireNative()
    {
        if (!NativeRawReady.Value)
            Assert.Skip("libraw_native not available (native wrappers not built for this platform).");
    }

    [Theory]
    [InlineData(".dng")]
    [InlineData(".CR3")]
    [InlineData(".nef")]
    [InlineData(".arw")]
    [InlineData(".raf")]
    public void CameraRawExtensions_AreRecognised(string extension)
    {
        Assert.Equal(ImageFormatType.Raw, ImageFormat.GetImageFormat(extension));
        Assert.True(ImageFormat.IsSupported(extension));
    }

    [Fact]
    public void TheGenericRawExtension_IsNotClaimed()
    {
        Assert.Equal(ImageFormatType.Unknown, ImageFormat.GetImageFormat(".raw"));
    }

    [Fact]
    public void ADng_DevelopsToSceneReferredLight()
    {
        RequireNative();

        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec(Level: 0.25)));

        Assert.True(composite.IsHdrDecoded);
        var content = Assert.IsType<HdrRasterContent>(composite.Content);
        Assert.Equal(64f, content.DecodedWidth);
        Assert.Equal(48f, content.DecodedHeight);

        // A flat gray mosaic stays gray, at its linear level times the exposure baseline - no curve.
        var gain = Assert.IsType<float>(content.Range.SceneWhite);
        var (r, g, b) = CentrePixel(content.Image);
        Assert.InRange(g / gain, 0.2f, 0.3f);
        Assert.InRange(r, g - 0.02f, g + 0.02f);
        Assert.InRange(b, g - 0.02f, g + 0.02f);
    }

    [Fact]
    public void ADng_IsDescribed()
    {
        RequireNative();

        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec()));
        var facts = composite.FormatSpecificSnapshot().ToDictionary(p => p.Key, p => p.Value);

        Assert.Equal("Bayer (RGGB)", facts["Sensor"]);
        Assert.Equal("1.4.0.0", facts["DNG Version"]);
        Assert.Equal("0 / 4095", facts["Black / White Level"]);
        Assert.Equal("None", facts["Embedded Preview"]);
        Assert.Equal("AHD", facts["Demosaic"]);
        Assert.StartsWith("LibRaw ", facts["Decoder"]);
    }

    [Fact]
    public void WithoutAPreview_TheExposureBaselineIsTheDefault()
    {
        RequireNative();

        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec()));
        var content = Assert.IsType<HdrRasterContent>(composite.Content);

        Assert.Equal(MathF.Pow(2f, RawExposure.FallbackStops), content.Range.SceneWhite!.Value, 0.001f);
        Assert.Equal(RawExposure.Peak, content.Range.Peak);
        Assert.Contains("default", Fact(composite, "Exposure Baseline"));

        // No preview, so no stand-in: developed directly, and said so.
        Assert.StartsWith("Developed in ", composite.Stage?.Text);
        Assert.False(composite.HdrPending);
    }

    [Fact]
    public void WithAPreview_TheExposureMatchesIt()
    {
        RequireNative();

        // Mosaic at 0.25 of white; preview (200, 100, 50), whose luminance is about 0.2 as light.
        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec(Level: 0.25, PreviewWidth: 40, PreviewHeight: 30, Orientation: 1)));
        var content = Assert.IsType<HdrRasterContent>(Renditions(composite).Active);

        Assert.Contains("matched", Fact(composite, "Exposure Baseline"));

        var stops = MathF.Log2(content.Range.SceneWhite!.Value);
        var previewLuminance = 0.2126f * Linear(200) + 0.7152f * Linear(100) + 0.0722f * Linear(50);
        var (_, g, _) = CentrePixel(content.Image);

        Assert.Equal(previewLuminance, RawExposure.Displayed(stops, g / content.Range.SceneWhite.Value), 0.01f);
    }

    [Fact]
    public void ADngWithItsOwnCurve_IsShownWithIt_AtItsOwnExposure()
    {
        RequireNative();

        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec(ToneCurve: [0f, 0f, 0.5f, 0.25f, 1f, 1f])));
        var content = Assert.IsType<HdrRasterContent>(composite.Content);

        Assert.NotNull(content.Range.Curve);
        Assert.Equal(0.25f, content.Range.Curve.Evaluate(0.5f), 0.01f);
        Assert.Same(content.Range.Curve, composite.DisplayedRange.Curve);
        Assert.StartsWith("The camera's own (3 points)", Fact(composite, "Tone Curve"));
        Assert.Contains("from the DNG", Fact(composite, "Exposure Baseline"));
    }

    [Fact]
    public void AGainTableMap_ScalesTheLight()
    {
        RequireNative();

        using var plain = Decode(DngBuilder.Build(new DngBuilder.Spec()));
        using var mapped = Decode(DngBuilder.Build(new DngBuilder.Spec(GainTableMap: DngBuilder.GainTableMap(1, 1, [2f], [0, 1, 0, 0, 0]))));

        var (_, before, _) = CentrePixel(Assert.IsType<HdrRasterContent>(plain.Content).Image);
        var (_, after, _) = CentrePixel(Assert.IsType<HdrRasterContent>(mapped.Content).Image);

        Assert.Equal(2f, after / before, 0.05f);
        Assert.Equal("1 x 1 tables of 2", Fact(mapped, "Local Tone Map"));
    }

    [Fact]
    public void TheGainTableMap_FollowsTheSensor_ThroughTheOrientation()
    {
        RequireNative();

        // On the sensor: gain 1 at the left edge, 3 at the right. Turned 90 degrees clockwise, the
        // sensor's left edge is the top of the picture.
        var map = DngBuilder.GainTableMap(1, 2, [1f, 3f], [0, 1, 0, 0, 0]);
        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec(Orientation: 6, GainTableMap: map)));
        var image = Assert.IsType<HdrRasterContent>(composite.Content).Image;

        Assert.Equal(48, image.Width);
        var top = PixelAt(image, 24, 3).G;
        var bottom = PixelAt(image, 24, 60).G;

        Assert.True(bottom / top > 2f, $"expected the bottom (sensor right) brighter, got top {top}, bottom {bottom}");
    }

    [Fact]
    public void ARotatedDng_IsShownUpright()
    {
        RequireNative();

        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec(Orientation: 6)));

        Assert.Equal(48f, composite.Content!.DecodedWidth);
        Assert.Equal(64f, composite.Content.DecodedHeight);
        Assert.Equal(ExifOrientation.Rotate90Cw, composite.AppliedOrientation);
    }

    [Fact]
    public void TheThumbnail_IsTheEmbeddedPreview()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec(PreviewWidth: 40, PreviewHeight: 30)));
        using var thumbnail = new RawDecoder().DecodeThumbnail(file.Path, 32, CancellationToken.None);

        Assert.NotNull(thumbnail);
        Assert.Equal(32, thumbnail.Width);
        Assert.Equal(24, thumbnail.Height);

        var pixel = thumbnail.GetPixel(16, 12);
        Assert.Equal((200, 100, 50), (pixel.Red, pixel.Green, pixel.Blue));
    }

    [Fact]
    public void ThePreview_TurnsWithTheRawData()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec(Orientation: 6, PreviewWidth: 40, PreviewHeight: 30)));
        using var thumbnail = new RawDecoder().DecodeThumbnail(file.Path, 64, CancellationToken.None);

        Assert.NotNull(thumbnail);
        Assert.Equal(30, thumbnail.Width);
        Assert.Equal(40, thumbnail.Height);
    }

    [Fact]
    public void WithoutAPreview_TheThumbnailIsDevelopedFromTheRawData()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec()));
        using var thumbnail = new RawDecoder().DecodeThumbnail(file.Path, 16, CancellationToken.None);

        Assert.NotNull(thumbnail);
        Assert.Equal(16, Math.Max(thumbnail.Width, thumbnail.Height));

        var pixel = thumbnail.GetPixel(thumbnail.Width / 2, thumbnail.Height / 2);
        Assert.InRange(pixel.Red - pixel.Green, -3, 3);
        Assert.InRange(pixel.Blue - pixel.Green, -3, 3);
    }

    [Fact]
    public async Task ThePreview_IsShownFirst_AndThenReplaced()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec(PreviewWidth: 40, PreviewHeight: 30)));
        using var composite = new Composite(new FileInfo(file.Path));
        var gate = new HoldingScheduler();

        await DecodeOn(gate, composite, TestContext.Current.CancellationToken);

        // The developed image is selected, with the preview standing in for it.
        var renditions = Renditions(composite);
        Assert.Equal(RawRenditions.Developed, renditions.ActiveIndex);

        var preview = Assert.IsType<RasterContent>(renditions.Active);
        Assert.IsNotType<HdrRasterContent>(preview);
        Assert.Equal(40, preview.Image.Width);
        Assert.False(composite.BackgroundDecodeTask.IsCompleted);

        // The panels can say what is on screen, and keep the HDR controls in place.
        Assert.Contains("developing", composite.Stage?.Text);
        Assert.True(composite.HdrPending);

        // The panel redraws only when told, so the EXIF read behind the preview must tell it.
        var exifShownBeforeTheSwap = false;
        composite.ProgressChanged += c => exifShownBeforeTheSwap |= c.ExifInfo is not null && renditions.Active is not HdrRasterContent;

        // The full size is known from the start, so fitting and zoom do not jump at the swap.
        Assert.Equal(64f, composite.LogicalWidth);
        Assert.Equal(48f, composite.LogicalHeight);

        gate.Release();
        await composite.BackgroundDecodeTask.WaitAsync(TimeSpan.FromSeconds(30), TestContext.Current.CancellationToken);

        Assert.IsType<HdrRasterContent>(renditions.Active);
        Assert.Equal(64f, composite.LogicalWidth);
        Assert.Null(renditions.WarningOf(RawRenditions.Developed));

        Assert.True(exifShownBeforeTheSwap, "no redraw was signalled once the EXIF had been read");
        Assert.StartsWith("Developed in ", composite.Stage?.Text);
        Assert.False(composite.HdrPending);

        // Still alive for a frame that may be drawing it, until the renderer lets go.
        Assert.NotEqual(IntPtr.Zero, preview.Image.Handle);
        renditions.ReleaseRetired();
        Assert.Equal(IntPtr.Zero, preview.Image.Handle);
    }

    [Fact]
    public async Task CancellingBehindThePreview_LeavesItUnfinishedAndUnwarned()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec(PreviewWidth: 40, PreviewHeight: 30)));
        using var composite = new Composite(new FileInfo(file.Path));
        using var cts = new CancellationTokenSource();
        var gate = new HoldingScheduler();

        await DecodeOn(gate, composite, cts.Token);
        cts.Cancel();
        gate.Release();

        await composite.BackgroundDecodeTask.WaitAsync(TimeSpan.FromSeconds(30), TestContext.Current.CancellationToken);

        Assert.Equal(CompositeState.Cancelled, composite.State);
        Assert.IsNotType<HdrRasterContent>(Renditions(composite).Active);
        Assert.Null(Renditions(composite).WarningOf(RawRenditions.Developed));
    }

    [Fact]
    public async Task APreviewOfAnotherShape_IsNotShownInPlaceOfTheImage()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec(PreviewWidth: 30, PreviewHeight: 30)));
        using var composite = new Composite(new FileInfo(file.Path));

        await new RawDecoder().DecodeAsync(composite, TestContext.Current.CancellationToken);

        // Developed at once instead, and the preview is still there to pick.
        Assert.True(composite.BackgroundDecodeTask.IsCompleted);

        var renditions = Renditions(composite);
        Assert.IsType<HdrRasterContent>(renditions.Active);
        Assert.Equal(2, renditions.Variants.Count);
    }

    [Fact]
    public void TheRenditions_AreTheDevelopedImageAndTheCamerasPreviews()
    {
        RequireNative();

        using var composite = Decode(DngBuilder.Build(new DngBuilder.Spec(PreviewWidth: 40, PreviewHeight: 30)));
        var renditions = Renditions(composite);

        Assert.Equal(VariantKind.Variants, renditions.Kind);
        Assert.Equal(["Developed", "Camera thumbnail"], renditions.Variants.Select(v => v.Label));
        Assert.Equal((64, 48), (renditions.Variants[0].Width, renditions.Variants[0].Height));
        Assert.Equal((40, 30), (renditions.Variants[1].Width, renditions.Variants[1].Height));
    }

    [Fact]
    public async Task PickingThePreview_ShowsItAtItsOwnSize()
    {
        RequireNative();

        // Kept for the whole test: a preview is read from the file when it is picked.
        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec(PreviewWidth: 40, PreviewHeight: 30)));
        using var composite = new Composite(new FileInfo(file.Path));

        await new RawDecoder().DecodeAsync(composite, TestContext.Current.CancellationToken);
        await composite.BackgroundDecodeTask.WaitAsync(TimeSpan.FromSeconds(30), TestContext.Current.CancellationToken);

        var renditions = Renditions(composite);
        var arrived = new TaskCompletionSource();
        renditions.VariantReady += _ => arrived.TrySetResult();
        renditions.VariantFailed += _ => arrived.TrySetResult();

        Assert.True(renditions.Select(1));
        await arrived.Task.WaitAsync(TimeSpan.FromSeconds(30), TestContext.Current.CancellationToken);

        Assert.Null(renditions.FailureOf(1)?.Description);
        var preview = Assert.IsType<RasterContent>(renditions.Active);
        Assert.IsNotType<HdrRasterContent>(preview);
        Assert.Equal(40f, composite.LogicalWidth);
        Assert.Equal(30f, composite.LogicalHeight);

        // And back: the developed image is still resident.
        Assert.True(renditions.Select(RawRenditions.Developed));
        Assert.IsType<HdrRasterContent>(renditions.Active);
        Assert.Equal(64f, composite.LogicalWidth);
    }

    [Fact]
    public async Task WhenTheRawDataCannotBeDeveloped_ThePreviewStaysWithAWarning()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec(PreviewWidth: 40, PreviewHeight: 30, MosaicMissing: true)));
        using var composite = new Composite(new FileInfo(file.Path));

        await new RawDecoder().DecodeAsync(composite, TestContext.Current.CancellationToken);
        await composite.BackgroundDecodeTask.WaitAsync(TimeSpan.FromSeconds(30), TestContext.Current.CancellationToken);

        var renditions = Renditions(composite);
        var preview = Assert.IsType<RasterContent>(renditions.Active);
        Assert.IsNotType<HdrRasterContent>(preview);
        Assert.Equal(40, preview.Image.Width);
        Assert.Equal(64f, composite.LogicalWidth);

        Assert.Null(composite.Stage);
        Assert.False(composite.HdrPending);

        // The warning belongs to the developed rendition, and carries LibRaw's own reason back
        // from the develop thread.
        var warning = renditions.WarningOf(RawRenditions.Developed);
        Assert.NotNull(warning);
        Assert.DoesNotContain("Failed to decode", warning.Detail);
        Assert.Null(composite.Warning);
    }

    [Fact]
    public void ATruncatedDng_FailsWithAReason()
    {
        RequireNative();

        var dng = DngBuilder.Build(new DngBuilder.Spec());
        var error = Assert.ThrowsAny<InvalidOperationException>(() => Decode(dng[..(dng.Length / 2)]).Dispose());

        Assert.False(string.IsNullOrWhiteSpace(error.Message));
    }

    [Fact]
    public void AFileThatIsNotRaw_FailsWithLibRawsReason()
    {
        RequireNative();

        var error = Assert.ThrowsAny<InvalidOperationException>(() => Decode(TempFile.Pattern(64 * 1024)).Dispose());

        Assert.Contains("LibRaw could not open", error.Message);
    }

    [Fact]
    public void ACancelledHandle_StopsDeveloping()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec()));
        using var image = RawNative.OpenFile(file.Path, out _);
        Assert.NotNull(image);

        RawNative.raw_cancel(image);
        var developed = RawNative.raw_develop(image, new RawNative.DevelopOptions { Demosaic = RawNative.DemosaicAhd }, out var pixels);

        Assert.False(developed);
        Assert.Equal(IntPtr.Zero, pixels.Owner);
        Assert.Contains("ancel", NativeErrors.GetUtf8ZOrAnsiZ(RawNative.get_last_raw_error()));
    }

    [Fact]
    public void AHandle_DevelopsOnlyOnce()
    {
        RequireNative();

        using var file = new TempFile(DngBuilder.Build(new DngBuilder.Spec()));
        using var image = RawNative.OpenFile(file.Path, out _);
        Assert.NotNull(image);

        var options = new RawNative.DevelopOptions { HalfSize = 1 };
        Assert.True(RawNative.raw_develop(image, options, out var first));
        RawNative.free_raw_pixels(first.Owner);

        Assert.False(RawNative.raw_develop(image, options, out var second));
        Assert.Equal(IntPtr.Zero, second.Owner);
    }

    /// <summary>Decodes on <paramref name="gate"/>, which holds the development queued behind the preview.</summary>
    private static Task DecodeOn(HoldingScheduler gate, Composite composite, CancellationToken ct) =>
        Task.Factory.StartNew(() => new RawDecoder().DecodeAsync(composite, ct), CancellationToken.None, TaskCreationOptions.None, gate).Unwrap();

    /// <summary>Runs the first task it is given and holds every later one until <see cref="Release"/>.</summary>
    private sealed class HoldingScheduler : TaskScheduler
    {
        private readonly List<Task> _held = [];
        private int _queued;

        public void Release()
        {
            Task[] held;
            lock (_held)
                held = [.. _held];

            foreach (var task in held)
                ThreadPool.QueueUserWorkItem(_ => TryExecuteTask(task));
        }

        protected override void QueueTask(Task task)
        {
            if (Interlocked.Increment(ref _queued) == 1)
            {
                ThreadPool.QueueUserWorkItem(_ => TryExecuteTask(task));
                return;
            }

            lock (_held)
                _held.Add(task);
        }

        protected override bool TryExecuteTaskInline(Task task, bool taskWasPreviouslyQueued) => false;

        protected override IEnumerable<Task> GetScheduledTasks()
        {
            lock (_held)
                return [.. _held];
        }
    }

    private static Composite Decode(byte[] file)
    {
        using var temp = new TempFile(file);
        var composite = new Composite(new FileInfo(temp.Path));

        try
        {
            new RawDecoder().DecodeAsync(composite, CancellationToken.None).GetAwaiter().GetResult();
            composite.BackgroundDecodeTask.GetAwaiter().GetResult();
            return composite;
        }
        catch
        {
            composite.Dispose();
            throw;
        }
    }

    private static VariantRasterContent Renditions(Composite composite) => Assert.IsType<VariantRasterContent>(composite.Content);

    private static string Fact(Composite composite, string key) => composite.FormatSpecificSnapshot().Single(p => p.Key == key).Value;

    private static float Linear(byte encoded)
    {
        var c = encoded / 255f;
        return c <= 0.04045f ? c / 12.92f : MathF.Pow((c + 0.055f) / 1.055f, 2.4f);
    }

    private static (float R, float G, float B) CentrePixel(SKImage image) => PixelAt(image, image.Width / 2, image.Height / 2);

    private static (float R, float G, float B) PixelAt(SKImage image, int x, int y)
    {
        var info = new SKImageInfo(1, 1, SKColorType.RgbaF32, SKAlphaType.Unpremul, SKColorSpace.CreateSrgbLinear());
        var pixel = new float[4];

        unsafe
        {
            fixed (float* p = pixel)
                Assert.True(image.ReadPixels(info, (IntPtr)p, 16, x, y));
        }

        return (pixel[0], pixel[1], pixel[2]);
    }
}